from solution import find


def test_issue_example_3_3():
    """Example: assert find(3,3) == 0."""
    assert find(3, 3) == 0  # 3 = 1*3 + 0


def test_issue_basic_remainder():
    """Rule: find remainder of two numbers with 10 and 3."""
    assert find(10, 3) == 1  # 10 = 3*3 + 1


def test_issue_exact_multiple():
    """Rule: find remainder of two numbers with 12 and 4."""
    assert find(12, 4) == 0  # 12 = 3*4 + 0


def test_issue_dividend_smaller_than_divisor():
    """Rule: find remainder of two numbers with 2 and 5."""
    assert find(2, 5) == 2  # 2 = 0*5 + 2


def test_issue_zero_dividend():
    """Rule: find remainder of two numbers with 0 and 5."""
    assert find(0, 5) == 0  # 0 = 0*5 + 0


def test_issue_divisor_one():
    """Rule: find remainder of two numbers with 9 and 1."""
    assert find(9, 1) == 0  # 9 = 9*1 + 0


def test_issue_just_above_multiple():
    """Rule: find remainder of two numbers just above multiple 8."""
    assert find(9, 4) == 1  # 9 = 2*4 + 1


def test_issue_just_below_multiple():
    """Rule: find remainder of two numbers just below multiple 8."""
    assert find(7, 4) == 3  # 7 = 1*4 + 3


def test_issue_operand_order():
    """Rule: find remainder of two numbers respects order n then m."""
    assert find(5, 3) == 2  # 5 = 1*3 + 2


def test_contract_large_values():
    """Contract: find remainder of two numbers works for large values."""
    assert find(100, 7) == 2  # 100 = 14*7 + 2


def test_contract_quotient_identity():
    """Contract: find remainder of two numbers satisfies n == q*m + r."""
    assert find(14, 5) == 4  # 14 = 2*5 + 4


def test_contract_remainder_less_than_divisor():
    """Contract: find remainder of two numbers is less than divisor."""
    assert find(17, 5) == 2  # 17 = 3*5 + 2, and 2 < 5
